head.script:
/*최상단 선언 */
scwin.isMain = function () {
    return true;
}

scwin.pgmId = 'PGJ111M01'
// 오늘 날짜
scwin.nowDate = WebSquare.date.getCurrentServerDate();
// 금주 경매일정 전역변수
scwin.rletPbanc = ''  // 부동산 일반공고
scwin.rletCrrctPbanc = '' // 부동산 정정공고
scwin.rletRtrcnPbanc = '' // 부동산 취소공고
scwin.mvprpGnrlPbanc = '' // 동산 일반공고
scwin.mvprpErlyPbanc = '' // 동산 조기공고

scwin.rletPbancCnt = 1; // 부동산 일반공고 리로드 횟수
scwin.rletCrrctPbancCnt = 1 // 부동산 정정공고 리로드 횟수
scwin.rletRtrcnPbancCnt = 1 // 부동산 취소공고 리로드 횟수
scwin.mvprpGnrlPbancCnt = 1 // 동산 일반공고 리로드 횟수
scwin.mvprpErlyPbancCnt = 1 // 동산 조기공고 리로드 횟수

// 빠른(신속)검색 부동산,동산 검색 flag
scwin.rpdtSrchBtnFlag = '01';


WebSquare.startAppalQ


/**
 * 메인페이지 onload
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.07.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function () {
    /* TO-DO */
    const userId = 'system';
    scglblo.setScUserId(userId); /* 유저id 등록 */
    scscrno.setScPgmId(scwin.pgmId); /* 화면id 등록 */
    // 경매 왼쪽아래 배너
    gpr_serviceGuide.hide(); // 안내서비스
    grp_auctnVt.hide(); // 투표하기
    //메인 slider+
    $('.slider_wrap .slider_list a.resi').attr('data-slide-index', '0');
    $('.slider_wrap .slider_list a.car').attr('data-slide-index', '1');
    $('.slider_wrap .slider_list a.comm').attr('data-slide-index', '2');
    $('.slider_wrap .slider_list a.land').attr('data-slide-index', '3');
    $('.slider_wrap .slider_list a.indust').attr('data-slide-index', '4');
    $('.slider_wrap .slider_list a.forest').attr('data-slide-index', '5');

    $('.main_slider').bxSlider({
        mode: 'fade',
        auto: true,
        stopAutoOnClick: true,
        pagerCustom: '.slider_list'
    });

    // 공지사항 slider
    $('.notice_wrap .notice_list').bxSlider({
        mode: 'horizontal',
        touchEnabled: false, //크롬에서 bxSilder는 오류가 몇개발생해서 해당 옵션을 추가해줘야 이벤트 발생
        auto: false,
        speed: 150,
        pager: false,
        // slideWidth: 350,
        maxSlides: 1,
        moveSlides: 1,
        onSliderLoad:function(){ /* 웹접근성 bx슬라이더 function추가 */
            $(".bx-clone").find("a").prop("tabIndex","-1");
        },
        onSlideAfter:function(){ /* 웹접근성 bx슬라이더 function추가 */
            $('.notice_wrap .notice_list').children("li").each(function(){
                if ($(this).attr("aria-hidden") == "false") {
                    $(this).find("a").attr("tabIndex",0);
                } else {
                    $(this).find("a").attr("tabIndex",1);
                }
            })
        }
    });

    /* 웹접근성 Enter이벤트를 추가하기 위한 로직 */
    const aDiv = document.querySelectorAll('.mainbox .info_list');
    aDiv.forEach(el=>{
        const aTags = el.querySelectorAll('a');
        aTags.forEach(a=>{
            a.addEventListener('keydown',function(e){
                let key = e.key;
                if (key == 'Enter' || key == 1) {
                    let id = this.id;

                    if(id == "mf_anc_pvsnSrvc"){
                        scwin.grp_pvsnSrvc_onclick();
                    } else if(id == "mf_anc_sitUtilGdnc"){
                        setTimeout(()=>{
                            scwin.grp_sitUtilGdncBtn_onclick()
                        },100)
                    } else if(id == "mf_anc_mvprpExecInf"){
                        scwin.grp_mvprpExecInfBtn_onclick();
                    } else {
                        scwin.grp_pvsnSrvc_onclick();
                    }
                }
            });
        });
    });


    // 금주경매 "일정 없음" hide
    tbx_rletGnrlNone.hide();
    //빠른물건 검색을 위해 부동산만 오픈
    sbx_mvprpRpdtCortLst.hide();
    grp_mvprpRpdtSrch.hide();
    //빠른물건검색 콤보박스 셋팅
    pgjUtil.bindSelectBox(pgjUtil.getCortOfcLst('B'), sbx_rletRpdtCortLst, false); // 법원 리스트
    sbx_rletRpdtCortLst.setSelectedIndex(1);
    pgjUtil.bindSelectBox(pgjUtil.getCortOfcLst('O'), sbx_mvprpRpdtCortLst, false);
    sbx_mvprpRpdtCortLst.setSelectedIndex(1);
    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst('Y', 'B', 'FB'), sbx_rletRpdtSdLst, false); // 시/도 리스트
    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst('Y', 'O', 'FB'), sbx_mvprpRpdtSdLst, false);
    pgjUtil.bindSelectBox(pgjUtil.getRnConsonantLst(), sbx_rletRpdtConsonant, false); // 자음모음 리스트
    sbx_rletRpdtConsonant.setSelectedIndex(0);
    pgjUtil.bindSelectBox(pgjUtil.getRnConsonantLst(), sbx_mvprpRpdtConsonant, false);
    sbx_mvprpRpdtConsonant.setSelectedIndex(0);

    // 소재지 시/도
    com.executeSubmission(sbm_selectMainInfo);

};

/* 웹접근성 bx슬라이더 수정 */
// $('.notice_wrap .notice_list a').focusin(function(){
//  noticSlider.stopAuto();
// })

scwin.onpageunload = function () {

};


/**
 * 공지사항 open팝업 method 실행
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.07.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.openNtcMtrPouUp = function (list) {
    if (list.length > 0) {
        /* 팝업창 여러개 일때 위치 조정 */
        var num = 100;
        var num2 = 100;
        let idNum = 0
        for (let i = 0; i < list.length; i++) {
            let cookieTemp = pgjUtil.getCookie(list[i].cortAuctnNtcMtrSeq)
            if (!(cookieTemp != null && cookieTemp == "Y")) {//현재 해당 공지사항 쿠키key값이 존재하지않은경우,팝업창 오픈
                /* 공지사항 open팝업 method 실행 */
                scwin.ntcMtrPopUp(idNum, list[i], num, num2);
                num -= 50;
                num2 -= 50;
                idNum++
            }
        }
    }
}



/**
 * 공지사항 open팝업 method
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.07.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ntcMtrPopUp = function (idNum, item, num, num2) {
    let modalFlag = false
    if (item.cortAuctnRletDvsCd === '0005803') modalFlag = true
    /********* Popup Settings *********/
    var winW = window.innerWidth;
    var winH = window.innerHeight;

    /* small popup size */
    var popupW = 700;
    var popupH = 600;

    var popupX = (winW / 2) - (popupW / 2) - num2;
    var popupY = (winH / 2) - (popupH / 2) - num;

    /**
     * 공지사항 openPopUp option설정
     */
    var options = {
        id: "ntcMtrPopUp" + idNum,
        type: "wframePopup",
        popupName: "공지사항",
        top: popupY,
        left: popupX,
        width: popupW,
        height: popupH,
        modal: modalFlag
    };

    /* 공지사항 팝업창이 오픈될때 같이 가져갈 paramether 변수 선언 */
    obj = {};
    /* 공지사항 팝업창에서 closePopUp시 실행시킬 callback 함수 */
    obj.callbackFn = "scwin.callbackFn";
    /* 공지사항 팝업창이 오픈될때 같이 가져갈 paramether */
    paramObj = {};
    paramObj.ntcEtcDtlDvsCd = item.cortAuctnNtcEtcDtlDvsCd
    paramObj.ntcEtcDvsCd = item.cortAuctnNtcEtcDvsCd
    paramObj.ntcMtrSeq = item.cortAuctnNtcMtrSeq
    paramObj.pstgBgngYmd = item.pstgBgngYmd
    obj.paramObj = paramObj;
    /* 공지사항 팝업창 open  */
    com.win.openPopup("/pgj/ui/pgj100/PGJ111P08.xml", options, obj);
};


/**
 * 공지사항 팝업창에서 상세보기 눌렀을 경우 발생될 callback함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.07.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.callbackFn = function (dataObj) {

    /**
     * 상세 페이지로 이동할 url 및 parameter
     */
    var path = "/pgj/ui/pgj100/PGJ141M02.xml";
    var moveData = {
        "cortAuctnNtcMtrSeq": dataObj.cortAuctnNtcMtrSeq
    };


    /**
     * $p.url options 설정
     */
    var options = {};
    options.spa = false;
    options.param = moveData;

    /**
     * moveData를 가지고 상세페이지로 이동
     */
    $p.url(path, options);

};

/**
 * main에서 사용할 데이터 조회후 맞게 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.19.   나해준       [NELS]최초 생성
 *  2026.07.07    김기석       [26A-PGJ-0030] 임차인통지서 QR코드를 통한 볍원경매정보 서비스 제공
 * ============= ============ ==========================
 */
scwin.sbm_selectMainInfo_submitdone = function ({ responseJSON: { data, status } }) {
    if (status === 200) {
        const result = data.result;
        const nwstVtInfo = result.nwstVtInfo; // 가장 최근투표
        const nwstNtcMtr = result.nwstNtcMtr // 최근공지사항 상위 3건
        const popNtcMtr = result.popNtcMtr // 팝어용으로 등록된 공지사항
        const gdsKnd = result.gdsKnd //용도별 물건정보
        let mjrtyGds = result.mjrtyItrtGds // 다수관심물건
        console.log("mjrtyGds ===>",mjrtyGds)
        console.log("result ===>",result)
        scwin.rletPbanc = scwin.weekAuctnScdleRletEvent(result.rletPbanc || '')  // 부동산 일반공고
        scwin.rletCrrctPbanc = scwin.weekAuctnScdleRletEvent(result.rletCrrctPbanc || '') // 부동산 정정공고
        scwin.rletRtrcnPbanc = scwin.weekAuctnScdleRletEvent(result.rletRtrcnPbanc || '') // 부동산 취소공고
        scwin.mvprpGnrlPbanc = scwin.weekAuctnScdleMvprpEvent(result.mvprpGnrlPbanc || '') // 동산 일반공고
        scwin.mvprpErlyPbanc = scwin.weekAuctnScdleMvprpEvent(result.mvprpErlyPbanc || '') // 동산 조기공고
        //팝업용 공지사항
        scwin.openNtcMtrPouUp(popNtcMtr)
        // 투표하기
        if (!scutilo.isEmpty(nwstVtInfo)) {
            grp_auctnVt.show(""); // 투표하기
            anc_auctnVtCtt.setValue(nwstVtInfo.qstnCtt);
        } else {
            gpr_serviceGuide.show(""); // 안내서비스
        }

        // 메인화면 매각율
        let dspslRate = scutilo.isEmpty(result.dspslRate.rate) ? 0.0 : result.dspslRate.rate;

        let year = scwin.nowDate.substring(0, 4);
        let mm = scwin.nowDate.substring(4, 6);
        spn_gdsRate.setValue(dspslRate)
        tbx_mainTitleDate.setValue(`${year}년 ${mm}월 매각가율`);

        // 금주 경매일정 공고 (부동산 일반공고 최초)
        if (scwin.rletPbanc.length > 0) {
            gen_rletGnrl.removeAll();
            scwin.rletPbanc[0].forEach((r, i) => {
                gen_rletGnrl.insertChild(i);
                gen_rletGnrl.getChild(i, 'spn_rletGnrlCortTitle').setValue(r.get('cortTitle'));
                if (r.get('disableFlag') !== '02') {
                    gen_rletGnrl.getChild(i, 'anc_rletGnrlDxdyTitle').setValue(r.get('dxdyTitle'));
                    gen_rletGnrl.getChild(i, 'anc_rletGnrlDxdyTitle').setUserData("grpNum", 0);
                    gen_rletGnrl.getChild(i, 'anc_rletGnrlDxdyTitle').setUserData("idx", i);
                    $("#mf_gen_rletGnrl_"+i+"_spn_rletGnrlDxdyTitle").hide();
                } else {
                    gen_rletGnrl.getChild(i, 'spn_rletGnrlDxdyTitle').setValue(r.get('dxdyTitle'));
                    $("#mf_gen_rletGnrl_"+i+"_anc_rletGnrlDxdyTitle").hide();
                }
                gen_rletGnrl.getChild(i, 'spn_rletGnrlBidDvsTitle').setValue(r.get('bidDvsNm'));
            })
        } else {
            tbx_rletGnrlNone.show("");
        }
        // 금주 경매 리로드 이벤트 추가
        if (scwin.rletPbanc.length > 1) {
            document.getElementById($p.getComponentById('btn_rletGnrlReload').id) /* 부동산 일반 공고 */
                .addEventListener('click', () => { scwin.pbncRletReload(scwin.rletPbanc, 'gen_rletGnrl', 'spn_rletGnrlCortTitle', 'anc_rletGnrlDxdyTitle', 'spn_rletGnrlBidDvsTitle') })
        } else {
            btn_rletGnrlReload.setDisabled(true)
        }
        // 금주 경매 웹접근성 처리
        // /* 웹접근성 TODO */
        // let tac = document.getElementById($p.getComponentById("tabControl2").id)
        // tac.querySelector('ul').querySelectorAll('li').forEach( (r,i)=>{
        //     if ( i == 0) {
        //      r.querySelector('a').title = "선택됨"
        //     } else {
        //      r.querySelector('a').title = "";
        //     }
        //     r.querySelector('a').setAttribute('role','button')
        // })
        // let tac = document.getElementById($p.getComponentById("tabControl1").id)
        // tac.querySelector('ul').querySelectorAll('li').forEach( (r,i)=>{
        //     if ( i == 0) {
        //      r.querySelector('a').title = "선택됨"
        //     } else {
        //      r.querySelector('a').title = "";
        //     }
        //     r.querySelector('a').setAttribute('role','button')
        // })
        // let tac = document.getElementById($p.getComponentById("tabControl3").id)
        // tac.querySelector('ul').querySelectorAll('li').forEach( (r,i)=>{
        //     if ( i == 0) {
        //      r.querySelector('a').title = "선택됨"
        //     } else {
        //      r.querySelector('a').title = "";
        //     }
        //     r.querySelector('a').setAttribute('role','button')
        // })



        //  좌측 공지사항
        nwstNtcMtr.forEach((r, i) => {
            let seq = i + 1
            $p.getComponentById(`anc_sideNtcMtr_${seq}`).setValue(r.ntatcTitlNm);
            $p.getComponentById(`anc_sideNtcMtr_${seq}`).setUserData('etcDvsCd', r.cortAuctnNtcEtcDvsCd);
            $p.getComponentById(`anc_sideNtcMtr_${seq}`).setUserData('ntcSeq', r.cortAuctnNtcMtrSeq);
            $p.getComponentById(`tbx_sideNtcMtrDate_${seq}`).setValue(scdateo.getFmtDate(r.pstgBgngYmd, '.'));
        })

        // 용도별 검색
        gdsKnd.forEach((r, i) => {
            let seq = i
            $p.getComponentById(`anc_usgGdsInf_${seq}`).setValue(r.dspslGdsNm);
            document.getElementById($p.getComponentById(`anc_usgGdsInf_${seq}`).id).addEventListener('click', () => {
                scwin.moveUsgSrch(r.emlScrnCtt)
            })
        })
        if (mjrtyGds.length > 0) {
            let cnt = 1 // 로컬 테스트용
            for (let i = 0; i < 3; i++) {
                $p.getComponentById(`tbx_mjrtyItrtGdsTitle_${i}`).setValue(mjrtyGds[i].dspslUsgNm) // 용도명

                /* 이미지 클릭 이벤트 */
                document.getElementById($p.getComponentById(`grp_wrapTag_${i}`).id).setAttribute("href","#")
                document.getElementById($p.getComponentById(`grp_wrapTag_${i}`).id).addEventListener('click', () => {
                 scwin.showPicPopUp(mjrtyGds[i])
                })
                document.getElementById($p.getComponentById(`grp_wrapTag_${i}`).id).addEventListener('keyup', () => {
                 if (e.code === 'Enter') scwin.showPicPopUp(mjrtyGds[i])
                })
                /* 주소 클릭, 엔터 이벤트 */
                $p.getComponentById(`tbx_mjrtyItrtGdsAddr_${i}`).setValue(mjrtyGds[i].printSt) // 물건 장소
                document.getElementById($p.getComponentById(`tbx_mjrtyItrtGdsAddr_${i}`).id).addEventListener('click', () => {
                 scwin.moveGdsDtlScrn(mjrtyGds[i])
                })
                document.getElementById($p.getComponentById(`tbx_mjrtyItrtGdsAddr_${i}`).id).addEventListener('keyup', () => {
                 if (e.code === 'Enter') scwin.moveGdsDtlScrn(mjrtyGds[i])
                })
                /* 최저매각가격 이벤트 */
                $p.getComponentById(`spn_mjrtyItrtGdsLwsAmt_${i}`).setValue(`${scutilo.getCommaFmt(mjrtyGds[i].minmaePrice)} 원`) //최저매각가격
                document.getElementById($p.getComponentById(`spn_mjrtyItrtGdsLwsAmt_${i}`).id).addEventListener('click', () => {
                 scwin.moveGdsDtlScrn(mjrtyGds[i])
                })
                document.getElementById($p.getComponentById(`spn_mjrtyItrtGdsLwsAmt_${i}`).id).addEventListener('keyup', () => {
                 if (e.code === 'Enter') scwin.moveGdsDtlScrn(mjrtyGds[i])
                })
                /* 감정평각금액 이벤트 */
                $p.getComponentById(`spn_mjrtyItrtGdsAeeAmt_${i}`).setValue(`${scutilo.getCommaFmt(mjrtyGds[i].gamevalAmt)} 원`) //감정평가금액
                document.getElementById($p.getComponentById(`spn_mjrtyItrtGdsAeeAmt_${i}`).id).addEventListener('click', () => {
                 scwin.moveGdsDtlScrn(mjrtyGds[i])
                })
                document.getElementById($p.getComponentById(`spn_mjrtyItrtGdsAeeAmt_${i}`).id).addEventListener('keyup', () => {
                 if (e.code === 'Enter') scwin.moveGdsDtlScrn(mjrtyGds[i])
                })
                /* TO-DO 데이터 파일 경로 수정해야함 /pgj/ 붙어야함 */
                let imgPath = (mjrtyGds[i].phtoInfo ?. picFile) ? `data:image/png;base64,${mjrtyGds[i].phtoInfo ?. picFile}`
                             : `/pgj/cm/images/sample/inter_sample${cnt}.png` // 개발서버용 TO-BE
                $p.getComponentById(`img_mjrtyItrtGdsImg_${i}`).setSrc(imgPath) // 이미지경로

                //[26A-PGJ-0000] 웹접근성(openWAX) 점검 수정
                document.getElementById($p.getComponentById(`img_mjrtyItrtGdsImg_${i}`).id).setAttribute("alt","다수 관심물건 " + mjrtyGds[i].dspslUsgNm);

                cnt++ // 로컬용, 개발 더미처리용(테스트)
            }
        }
        /* 웹접근성 "금주경매 의미없는 a태그 삭제" */
        const tapId = $p.getComponentById('tabControl2').id
        const docNode = document.getElementById(tapId);
        const nodeLst = docNode.querySelectorAll('.w2tabcontrol_contents')
        nodeLst.forEach(r=>{
            let childNode = r.querySelector('.w2tabcontrol_bridge')
            if (childNode) r.removeChild(childNode)
        })
    }
};

/**
 *
 * 해당 다수관심 물건클릭시 상세화면으로 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.26.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.moveGdsDtlScrn = function (item) {
    const gds = item

    const param = {
        pgmId: scwin.pgmId,
        scNo: gds.saNo,
        cortOfcCd: gds.boCd,
        dspslGdsSeq: gds.maemulSer,
        prevInfo: 'none',
        srchInfo: {
            sideDvsCd: '2',
            menuNm: '다수관심물건'
        }
    }
    pgjUtil.openGdsDtl(param);
}

