/**
 *
 * main화면 플래시 부분 클릭시 해당 용도 조건으로 물건 검색
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.19.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.mainMoveIcon = function (dvsFlag) {
    const flag = dvsFlag;
    let param = {};
    let srchInfo = '';
    param.pgmId = 'mainUsg';
    param.scNo = 'none';
    param.cortOfcCd = 'none';
    param.dspslGdsSeq = 'none';
    param.prevInfo = 'none';
    // AS-IS 코드값으로 사용
    switch (flag) {
        case '01': // 주거용 건물
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd : '20000',
                mclDspslGdsLstUsgCd : '20100',
                sclDspslGdsLstUsgCd : ''
            }
            break;
        case '02': // 상가용 건물
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd: '20000',
                mclDspslGdsLstUsgCd: '21100',
                sclDspslGdsLstUsgCd: ''
            }
            break;
        case '03': // 자동차
            srchInfo = {
                cortAuctnSrchCondCd: '0004603',
                lclDspslGdsLstUsgCd: '30000',
                mclDspslGdsLstUsgCd: '30100',
                sclDspslGdsLstUsgCd: '',
                menuNm : '자동차·중기검색'
            }
            param.pgmId = 'mainUsgCar'
            break;
        case '04': // 산업용 건물
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd: '20000',
                mclDspslGdsLstUsgCd: '22100',
                sclDspslGdsLstUsgCd: ''
            }
            break;
        case '05': // 토지
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd: '10000',
                mclDspslGdsLstUsgCd: '10100',
                sclDspslGdsLstUsgCd: ''
            }
            break;
        case '06': // 임야
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd: '10000',
                mclDspslGdsLstUsgCd: '10100',
                sclDspslGdsLstUsgCd: '10105'
            }
            break;
    }
    param.srchInfo = srchInfo
    pgjUtil.openGdsDtl(param);
}

