/**
 *
 *  부동산 탭 이동시 금주 경매 셋팅
 *  (alwaysDraw를 이용해 화면 리로드시 전부 렌더링 시키고 작업하려 했으나
 *  프로젝트 특성상 비동기가 원칙이라 탭 전체가 리로드 되는 시간이랑 맞지 않아 탭이동할때
 *  마다 해당 탭을 랜더링 시키는 방식으로 바꿈)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.20.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.tabControl1_onchange = function (tabID, idx, userTabID) {
    const levelDiv = document.querySelectorAll('.schd_tab_type2');
    levelDiv.forEach(el=>{
        const aTags = el.querySelectorAll('a');
        aTags.forEach(a=>{
            a.title = ""
        });
    });

    const flag = idx
    switch (flag) {
        case 0:
            if (scwin.rletPbanc.length > 0) { // 부동산 일반공고
                gen_rletGnrl.removeAll();
                scwin.rletPbanc[0].forEach((r, i) => {
                    gen_rletGnrl.insertChild(i);
                    gen_rletGnrl.getChild(i, 'spn_rletGnrlCortTitle').setValue(r.get('cortTitle'));
                    if (r.get('disableFlag') !== '02') {
                        gen_rletGnrl.getChild(i, 'anc_rletGnrlDxdyTitle').setValue(r.get('dxdyTitle'));
                        gen_rletGnrl.getChild(i, 'anc_rletGnrlDxdyTitle').setUserData("grpNum", 0);
                        gen_rletGnrl.getChild(i, 'anc_rletGnrlDxdyTitle').setUserData("idx", i);
                        $("#mf_gen_rletGnrl_"+i+"_spn_rletGnrlDxdyTitle").hide();
                    } else {
                        gen_rletGnrl.getChild(i, 'spn_rletGnrlDxdyTitle').setValue(r.get('dxdyTitle'));
                        $("#mf_gen_rletGnrl_"+i+"_anc_rletGnrlDxdyTitle").hide();
                    }
                    gen_rletGnrl.getChild(i, 'spn_rletGnrlBidDvsTitle').setValue(r.get('bidDvsNm'));
                })
            } else {
                tbx_rletGnrlNone.show("");
                btn_rletGnrlReload.hide();
            }
            break;
        case 1:
            tbx_rletCrrctNone.hide();
            if (scwin.rletCrrctPbanc.length > 0) { // 부동산 정정공고
                document.getElementById($p.getComponentById('btn_rletCrrctReload').id) /* 부동산 정정 공고 */
                .addEventListener('click', () => { scwin.pbncRletReload(scwin.rletCrrctPbanc, 'gen_rletCrrct', 'spn_rletCrrctCortTitle', 'anc_rletCrrctDxdyTitle', 'spn_rletCrrctBidDvsTitle') })

                if (scwin.rletCrrctPbanc.length === 1) btn_rletCrrctReload.setDisabled(true);
                gen_rletCrrct.removeAll();
                scwin.rletCrrctPbanc[0].forEach((r, i) => {
                    gen_rletCrrct.insertChild(i);
                    gen_rletCrrct.getChild(i, 'spn_rletCrrctCortTitle').setValue(r.get('cortTitle'));
                    if (r.get('disableFlag') !== '02') {
                        gen_rletCrrct.getChild(i, 'anc_rletCrrctDxdyTitle').setValue(r.get('dxdyTitle'));
                        gen_rletCrrct.getChild(i, 'anc_rletCrrctDxdyTitle').setUserData("grpNum", 0);
                        gen_rletCrrct.getChild(i, 'anc_rletCrrctDxdyTitle').setUserData("idx", i);
                        $("#mf_gen_rletCrrct_"+i+"_spn_rletCrrctDxdyTitle").hide();
                    } else {
                        gen_rletCrrct.getChild(i, 'spn_rletCrrctDxdyTitle').setValue(r.get('dxdyTitle'));
                        $("#mf_gen_rletCrrct_"+i+"_anc_rletCrrctDxdyTitle").hide();
                    }
                    gen_rletCrrct.getChild(i, 'spn_rletCrrctBidDvsTitle').setValue(r.get('bidDvsNm'));
                })
            } else {
                tbx_rletCrrctNone.show("");
                btn_rletCrrctReload.hide();
            }
            break;
        case 2:
            tbx_rletRtrcnNone.hide();
            if (scwin.rletRtrcnPbanc.length > 0) { // 부동산 정정공고
                document.getElementById($p.getComponentById('btn_rletRtrcnReload').id) /* 부동산 취소 공고 */
                .addEventListener('click', () => { scwin.pbncRletReload(scwin.rletRtrcnPbanc, 'gen_rletRtrcn', 'spn_rletRtrcnCortTitle', 'anc_rletRtrcnDxdyTitle', 'anc_rletRtrcnBidDvsTitle') })
                if (scwin.rletRtrcnPbanc.length === 1) btn_rletRtrcnReload.setDisabled(true);
                gen_rletRtrcn.removeAll();
                scwin.rletRtrcnPbanc[0].forEach((r, i) => {
                    gen_rletRtrcn.insertChild(i);
                    gen_rletRtrcn.getChild(i, 'spn_rletRtrcnCortTitle').setValue(r.get('cortTitle'));
                    if (r.get('disableFlag') !== '02') {
                        gen_rletRtrcn.getChild(i, 'anc_rletRtrcnDxdyTitle').setValue(r.get('dxdyTitle'));
                        gen_rletRtrcn.getChild(i, 'anc_rletRtrcnDxdyTitle').setUserData("grpNum", 0);
                        gen_rletRtrcn.getChild(i, 'anc_rletRtrcnDxdyTitle').setUserData("idx", i);
                        $("#mf_gen_rletRtrcn_"+i+"_spn_rletRtrcnDxdyTitle").hide();
                    } else {
                        gen_rletRtrcn.getChild(i, 'spn_rletRtrcnDxdyTitle').setValue(r.get('dxdyTitle'));
                        $("#mf_gen_rletRtrcn_"+i+"_anc_rletRtrcnDxdyTitle").hide();
                    }
                    gen_rletRtrcn.getChild(i, 'anc_rletRtrcnBidDvsTitle').setValue(r.get('bidDvsNm'));
                })
            } else {
                tbx_rletRtrcnNone.show("");
                btn_rletRtrcnReload.hide();
            }
            break;
    }
    let tabNode = $p.getComponentById(tabID)
    tabNode.querySelector('a').title = '선택됨'
};

