scwin.tabControl3_onchange = function (tabID, idx, userTabID) {
    const levelDiv = document.querySelectorAll('.schd_tab_type2');
    levelDiv.forEach(el=>{
        const aTags = el.querySelectorAll('a');
        aTags.forEach(a=>{
            a.title = ""
        });
    });
    if (idx === 1) {
        if (scwin.mvprpErlyPbanc.length > 0) { // 부동산 조기공고
            document.getElementById($p.getComponentById('btn_mvprpErlyReload').id) /* 동산 조기 공고 */
                .addEventListener('click', () => { scwin.pbncMvprpReload(scwin.mvprpErlyPbanc, 'gen_mvprpErly', 'spn_mvprpErlyCortTitle', 'anc_mvprpErlyDxdyTitle', 'spn_mvprpErlyBidDvsTitle') })

            tbx_mvprpErlyNone.hide();
            if (scwin.mvprpErlyPbanc.length === 1) btn_mvprpErlyReload.setDisabled(true);
            gen_mvprpErly.removeAll();
            scwin.mvprpErlyPbanc[0].forEach((r, i) => {
                gen_mvprpErly.insertChild(i);
                gen_mvprpErly.getChild(i, 'spn_mvprpErlyCortTitle').setValue(r.get('cortTitle'));
                if (r.get('disableFlag') !== '02') {
                    gen_mvprpErly.getChild(i, 'anc_mvprpErlyDxdyTitle').setValue(r.get('toTalCntTitle'));
                    gen_mvprpErly.getChild(i, 'spn_mvprpErlyBidDvsTitle').setValue(r.get('progCntTitle'));
                    gen_mvprpErly.getChild(i, 'anc_mvprpErlyDxdyTitle').setUserData("grpNum", 0);
                    gen_mvprpErly.getChild(i, 'anc_mvprpErlyDxdyTitle').setUserData("idx", i);
                    gen_mvprpErly.getChild(i, 'spn_mvprpErlyDxdyTitle').hide();
                } else {
                    gen_mvprpErly.getChild(i, 'spn_mvprpErlyDxdyTitle').setValue(r.get('dxdyTitle'));
                    gen_mvprpErly.getChild(i, 'anc_mvprpErlyDxdyTitle').hide();
                }
            })
        } else {
            tbx_mvprpErlyNone.show("");
            btn_mvprpErlyReload.hide();
        }
    }
    let tabNode = $p.getComponentById(tabID)
    tabNode.querySelector('a').title = '선택됨'
};

/**
 *
 * 금주의 경매일정 부동산 5개씩 리로드 하는 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.20.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pbncRletReload = function (item, genId, cortTitle, dxdyTitle, bidDvsTitle) {

    let flag = cortTitle
    let cnt = 0;
    let gen = $p.getComponentById(`${genId}`);
    switch (flag) {
        case 'spn_rletGnrlCortTitle': //부동산 일반 공고
            cnt = scwin.rletPbancCnt;
            break;
        case 'spn_rletCrrctCortTitle': //부동산 정정 공고
            cnt = scwin.rletCrrctPbancCnt;
            break;
        case 'spn_rletRtrcnCortTitle': //부동산 취소 공고
            cnt = scwin.rletRtrcnPbancCnt;
            break;
    }
    if (cnt === 1) {
        gen.removeAll();
        item[cnt].forEach((r, i) => {
            gen.insertChild(i);
            gen.getChild(i, cortTitle).setValue(r.get('cortTitle'));
            gen.getChild(i, dxdyTitle).setValue(r.get('dxdyTitle'));
            gen.getChild(i, dxdyTitle).setUserData("grpNum", cnt);
            gen.getChild(i, dxdyTitle).setUserData("idx", i);
            gen.getChild(i, bidDvsTitle).setValue(r.get('bidDvsNm'));
            if (r.get('disableFlag') === '02') gen.getChild(i, dxdyTitle).setDisabled(true)
        })
        if (flag === 'spn_rletGnrlCortTitle') scwin.rletPbancCnt++
        if (flag === 'spn_rletCrrctCortTitle') scwin.rletCrrctPbancCnt++
        if (flag === 'spn_rletRtrcnCortTitle') scwin.rletRtrcnPbancCnt++
    } else {
        if (cnt < item.length) {
            gen.removeAll();
            item[cnt].forEach((r, i) => {
                gen.insertChild(i);
                gen.getChild(i, cortTitle).setValue(r.get('cortTitle'));
                gen.getChild(i, dxdyTitle).setValue(r.get('dxdyTitle'));
                gen.getChild(i, dxdyTitle).setUserData("grpNum", cnt);
                gen.getChild(i, dxdyTitle).setUserData("idx", i);
                gen.getChild(i, bidDvsTitle).setValue(r.get('bidDvsNm'));
                if (r.get('disableFlag') === '02') gen.getChild(i, dxdyTitle).setDisabled(true)
            })
