            if (flag === 'spn_rletCrrctCortTitle') scwin.rletCrrctPbancCnt++
            if (flag === 'spn_rletRtrcnCortTitle') scwin.rletRtrcnPbancCnt++
        } else {
            gen.removeAll();
            item[0].forEach((r, i) => {
                gen.insertChild(i);
                gen.getChild(i, cortTitle).setValue(r.get('cortTitle'));
                gen.getChild(i, dxdyTitle).setValue(r.get('dxdyTitle'));
                gen.getChild(i, dxdyTitle).setUserData("grpNum", "0");
                gen.getChild(i, dxdyTitle).setUserData("idx", i);
                gen.getChild(i, bidDvsTitle).setValue(r.get('bidDvsNm'));
                if (r.get('disableFlag') === '02') gen.getChild(i, dxdyTitle).setDisabled(true)
            })
            if (flag === 'spn_rletGnrlCortTitle') scwin.rletPbancCnt = 1
            if (flag === 'spn_rletCrrctCortTitle') scwin.rletCrrctPbancCnt = 1
            if (flag === 'spn_rletRtrcnCortTitle') scwin.rletRtrcnPbancCnt = 1
        }
    }
}

/**
 *
 * 금주의 동산 5개씩 리로드 하는 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.20.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pbncMvprpReload = function (item, genId, cortTitle, toTalCntTitle, progCntTitle) {
    let flag = cortTitle
    let cnt = 0;
    const gen = $p.getComponentById(`${genId}`)
    switch (flag) {
        case 'spn_mvprpGnrlCortTitle': //동산 일반 공고
            cnt = scwin.mvprpGnrlPbancCnt;
            break;
        case 'spn_mvprpErlyCortTitle': //동산 조기 공고
            cnt = scwin.mvprpErlyPbancCnt;
            break;
    }
    if (cnt === 1) {
        gen.removeAll();
        item[cnt].forEach((r, i) => {
            gen.insertChild(i);
            gen.getChild(i, cortTitle).setValue(r.get('cortTitle'));
            gen.getChild(i, toTalCntTitle).setValue(r.get('toTalCntTitle'));
            gen.getChild(i, toTalCntTitle).setUserData("grpNum", cnt);
            gen.getChild(i, toTalCntTitle).setUserData("idx", i);
            gen.getChild(i, progCntTitle).setValue(r.get('progCntTitle'));
            if (r.get('disableFlag') === '02') {
                gen.getChild(i, cortTitle).setDisabled(true)
                gen.getChild(i, toTalCntTitle).setDisabled(true)
                gen.getChild(i, progCntTitle).setDisabled(true)
            }
        })
        if (flag === 'spn_mvprpGnrlCortTitle') {
            scwin.mvprpGnrlPbancCnt++
        } else {
            scwin.mvprpErlyPbancCnt++
        }
    } else {
        if (cnt < item.length) {
            gen.removeAll();
            item[cnt].forEach((r, i) => {
                gen.insertChild(i);
                gen.getChild(i, cortTitle).setValue(r.get('cortTitle'));
                gen.getChild(i, toTalCntTitle).setValue(r.get('toTalCntTitle'));
                gen.getChild(i, toTalCntTitle).setUserData("grpNum", cnt);
                gen.getChild(i, toTalCntTitle).setUserData("idx", i);
                gen.getChild(i, progCntTitle).setValue(r.get('progCntTitle'));
                if (r.get('disableFlag') === '02') {
                    gen.getChild(i, cortTitle).setDisabled(true)
                    gen.getChild(i, toTalCntTitle).setDisabled(true)
                    gen.getChild(i, progCntTitle).setDisabled(true)
                }
            })
            if (flag === 'spn_mvprpGnrlCortTitle') {
                scwin.mvprpGnrlPbancCnt++
            } else {
                scwin.mvprpErlyPbancCnt++
            }
        } else {
            gen.removeAll();
            item[0].forEach((r, i) => {
                gen.insertChild(i);
                gen.getChild(i, cortTitle).setValue(r.get('cortTitle'));
                gen.getChild(i, toTalCntTitle).setValue(r.get('toTalCntTitle'));
                gen.getChild(i, toTalCntTitle).setUserData("grpNum", "0");
                gen.getChild(i, toTalCntTitle).setUserData("idx", i);
                gen.getChild(i, progCntTitle).setValue(r.get('progCntTitle'));
                if (r.get('disableFlag') === '02') {
                    gen.getChild(i, cortTitle).setDisabled(true)
                    gen.getChild(i, toTalCntTitle).setDisabled(true)
                    gen.getChild(i, progCntTitle).setDisabled(true)
                }
            })
            if (flag === 'spn_mvprpGnrlCortTitle') {
                scwin.mvprpGnrlPbancCnt = 1;
            } else {
                scwin.mvprpErlyPbancCnt = 1;
            }
        }
    }
}

/**
 * 금주 경매일정 부동산 일정 데이터의 맞게 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.19.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.weekAuctnScdleRletEvent = function (item) {
    let mapLst = new Array();
    let lst = item
    if (lst.length > 0) {
        lst.forEach((r, i) => {
            const orgData = Object.entries(r); // entri로 꺼내사
            let itmMap = new Map([...orgData]); // 스프레드 연산자로 합치기
            let customCortNm = scutilo.isEmpty(r.cortSptNm) ? '' : r.cortSptNm.replaceAll("지방법원", "").replaceAll("지원", "")
            let jdbnNm = scutilo.isEmpty(r.cortAuctnJdbnNm) ? '' : r.cortAuctnJdbnNm.replaceAll("경매", "")
            let dspslDxdyYmd = !scutilo.isEmpty(r.dspslDxdyYmd) ? `${r.dspslDxdyYmd.substring(4, 6)}.${r.dspslDxdyYmd.substring(6, 8)}` : '';
            let bidBgngYmd = !scutilo.isEmpty(r.bidBgngYmd) ? `${r.bidBgngYmd.substring(4, 6)}.${r.bidBgngYmd.substring(6, 8)}` : '';
            let cortTitle = `${customCortNm} ${jdbnNm}` // 법원명
            let dxdyTitle = r.bidDvsCd === `000331` ? dspslDxdyYmd : bidBgngYmd // 매각기일
            let bidDvsNm = '' // 입찰구분명
            let disableFlag = '01';
            if ((r.bidDvsCd === '000331' && Number(scwin.nowDate) <= Number(r.dspslDxdyYmd))
                || (r.bidDvsCd === '000332' && Number(scwin.nowDate) <= Number(r.bidBgngYmd))) {
                bidDvsNm = r.bidDvsCd === '000331' ? `(기일)` : `(기간)`
            } else {
                bidDvsNm = `(완료)`
                disableFlag = '02';
            }
            /* 운영 시나리오 테스트로 인한 TODO */
            if (r.dspslDxdyYmd == '20240719') {
                bidDvsNm = r.bidDvsCd === '000331' ? `(기일)` : `(기간)`
                disableFlag = '01';
            }
            itmMap.set('cortTitle', cortTitle)
            itmMap.set('bidDvsNm', bidDvsNm)
            itmMap.set('dxdyTitle', dxdyTitle)
            itmMap.set('disableFlag', disableFlag)
            mapLst.push(itmMap)
        })
        // 빈 배열 생성
        let result = new Array();
        for (let i = 0; i < mapLst.length; i += 5) {
            let tempArray;
            // slice() 메서드를 사용하여 특정 길이만큼 배열을 분리함
            tempArray = mapLst.slice(i, i + 5);
            // 빈 배열에 특정 길이만큼 분리된 배열을 추가
            result.push(tempArray);
        }
        return result;
    } else {
        return '';
    }
}

/**
 *
 * 금주 경매일정 동산 일정 데이터의 맞게 셋팅
