                mclDspslGdsLstUsgCd : '30100',
                sclDspslGdsLstUsgCd : '30101'
            }
            break;
        case '20102': // 다가구주택
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd : '20000',
                mclDspslGdsLstUsgCd : '20100',
                sclDspslGdsLstUsgCd : '20102'
            }
            break;
        case '20105': // 연립주택
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd : '20000',
                mclDspslGdsLstUsgCd : '20100',
                sclDspslGdsLstUsgCd : '20105'
            }
            break;
        case '20106': // 다세대주택
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd : '20000',
                mclDspslGdsLstUsgCd : '20100',
                sclDspslGdsLstUsgCd : '20106'
            }
            break;
        case '21104': // 판매시설
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd : '20000',
                mclDspslGdsLstUsgCd : '21100',
                sclDspslGdsLstUsgCd : '21104'
            }
            break;
        case '30101': // 오피스텔
            srchInfo = {
                cortAuctnSrchCondCd: '0004601',
                lclDspslGdsLstUsgCd : '20000',
                mclDspslGdsLstUsgCd : '20100',
                sclDspslGdsLstUsgCd : '20110'
            }
            break;
    }
    param.srchInfo = srchInfo
    pgjUtil.openGdsDtl(param);
}

/**
 *
 * 다수관심물건에서 사진 클릭시 사진 팝업창 오픈
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.26.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.showPicPopUp = function (param) {

    if (pgjUtil.popupDpcnChk('showPicPopUp')) {
        /********* Popup Settings *********/
        let winW = window.innerWidth;
        let winH = window.innerHeight;
        /* small popup size */
        /* small popup size */
        let popupW = 807;
        let popupH = 767;
        let popupX = (winW / 2) - (popupW / 2);
        let popupY = (winH / 2) - (popupH / 2);
        /**
         * 공지사항 openPopUp option설정
         */
        let options = {
            id: 'showPicPopUp',
            type: "wframePopup",
            popupName: "사진보기",
            top: popupY,
            left: popupX,
            width: popupW,
            height: popupH,
            modal: false
        };
        obj = {};
        paramObj = {};
        paramObj.pgmId = `PGJ111M01`
        paramObj.cortOfcCd = param.boCd;
        paramObj.csNo = param.saNo;
        // 결함처리용 TODO ====================
        // paramObj.cortOfcCd = 'B000210';
        // paramObj.csNo = '20240130050425';
        // TODO =====================
        obj.paramObj = paramObj;
        /* 공지사항 팝업창 open  */
        com.win.openPopup("/pgj/ui/pgj100/PGJ15BP06.xml", options, obj);
    } else {
        let item = {
            pgmId: `PGJ111M01`,
            cortOfcCd: param.boCd,
            csNo: param.saNo,
        }
        document.body.scrollTop = 0;
        // 팝업 scope에 접근 하여 콜백함수 호출
        WebSquare.uiplugin.popup.popupList[0].popupWin.childControlList[0].scope.scwin.mainCallBackFuntion(item)
    }
};

/**
 *
 * 빠른물건 검색 부동산,동산 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.26.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.rpdtSrchBtnEvent = function (flag) {
    if (flag === '01') {
        btn_rletRpdt.addClass('active')
        btn_rletRpdt.setTitle("빠른물건검색 부동산 선택");
        btn_mvprpRpdt.removeClass('active')
        btn_mvprpRpdt.setTitle("빠른물건검색 동산");
        scwin.rpdtSrchBtnFlag = '01'
        sbx_rletRpdtCortLst.show("");
        grp_rletRpdtSrch.show("");
        sbx_mvprpRpdtCortLst.hide();
        grp_mvprpRpdtSrch.hide();
    } else if (flag === '02') {
        btn_mvprpRpdt.addClass('active')
        btn_mvprpRpdt.setTitle("빠른물건검색 동산 선택");
        btn_rletRpdt.removeClass('active')
        btn_rletRpdt.setTitle("빠른물건검색 부동산");
        scwin.rpdtSrchBtnFlag = '02'
        sbx_mvprpRpdtCortLst.show("");
        grp_mvprpRpdtSrch.show("");
        sbx_rletRpdtCortLst.hide();
        grp_rletRpdtSrch.hide();
    }
}

