/**
 *
 * 빠른물건 검색버튼 클릭시 빠른물건 검색
 *
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.10.10.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_quickSearchGds_onclick = function (e) {

    if (scwin.rpdtSrchBtnFlag === '01') {
        if (scutilo.isEmpty(sbx_rletRpdtCortLst.getValue()) && scutilo.isEmpty(sbx_rletRpdtSdLst.getValue())) {
            scutilo.showMsg(scglblo.MSG.WARN,"법원을 전체로 선택할 경우 시/도 검색조건을 설정하세요")
            sbx_rletRpdtSdLst.focus();
            return false
        }
    } else {
        if (scutilo.isEmpty(sbx_mvprpRpdtCortLst.getValue()) && scutilo.isEmpty(sbx_mvprpRpdtSdLst.getValue())) {
            scutilo.showMsg(scglblo.MSG.WARN,"법원을 전체로 선택할 경우 시/도 검색조건을 설정하세요")
            sbx_mvprpRpdtSdLst.focus();
            return false
        }

    }


    let param = {};
    param.scNo = 'none';
    param.cortOfcCd = 'none';
    param.dspslGdsSeq = 'none';
    param.prevInfo = 'none';
    let cortOfcCd = "" //법원사무소
    let mvprpRletDvsCd = ""// 부동산,동산구분 코드
    let rprsAdongSdCd =  "" //	부동산지번시도코드
    let rprsAdongSggCd = "" //	부동산지번시군구코드
    let rprsAdongEmdCd = ""	// 부동산지번읍면동코드
    let rdnmSdCd = "" // 부동산 소재지(지번) 시/도
    let rdnmSggCd = "" // 부동산 소재지(새주소) 시/군/구
    let rdnmNo = "" // 부동산 소재지(새주소) 도로명
    let rdDspslPlcAdongSdCd = "" //동산 도로명 시/도 코드
    let rdDspslPlcAdongSggCd = ""//동산 도로명 시/군/구 코드
    let rdDspslPlcAdongEmdCd = ""//동산 도로명 코드
    let mvprpDspslPlcAdongSdCd = "" // 동산 지번 시도
    let mvprpDspslPlcAdongSggCd = "" // 동산 지번 시군구
    let mvprpDspslPlcAdongEmdCd = "" // 동산 지번 읍면동
    let cortAuctnSrchCondCd = "0004601"
    let cortStDvs = "";
    if (scwin.rpdtSrchBtnFlag === '01') { // 부동산
        param.pgmId = 'mainUsg';
        mvprpRletDvsCd = '00031R'
        cortAuctnSrchCondCd = '0004601'
        if ( !scutilo.isEmpty(sbx_rletRpdtCortLst.getValue()) ) {
            cortStDvs = '1'
            cortOfcCd = sbx_rletRpdtCortLst.getValue();
        } else {
            let rdnmNoTemp1 = sbx_rletRpdtEmdLst.getValue();

            let rdnmNoTemp2 = rdnmNoTemp1.split("|")
            if (rdnmNoTemp2[1] === 'A') {
                cortStDvs = '2' //지번 주소
                rprsAdongSdCd = sbx_rletRpdtSdLst.getValue();
                rprsAdongSggCd = sbx_rletRpdtSggLst.getValue();
                rprsAdongEmdCd = rdnmNoTemp2[0]
            } else if (rdnmNoTemp2[1] === 'R') {
                cortStDvs = '3' //도로명 주소
                rdnmSdCd = sbx_rletRpdtSdLst.getValue();
                rdnmSggCd = sbx_rletRpdtSggLst.getValue();
                rdnmNo = rdnmNoTemp2[0]
            } else {
                cortStDvs = '2' //지번 주소
                rprsAdongSdCd = sbx_rletRpdtSdLst.getValue();
                rprsAdongSggCd = sbx_rletRpdtSggLst.getValue();
            }
        }
    } else { //동산 TO-DO 검색결과 화면이 동산 따로만들어야함
        param.pgmId = "mvprpSrch"
        mvprpRletDvsCd = '00031M'
        cortAuctnSrchCondCd = '0004604'
        if (!scutilo.isEmpty(sbx_mvprpRpdtCortLst.getValue())) {
            cortStDvs = '1'
            cortOfcCd = sbx_mvprpRpdtCortLst.getValue();
        } else {
            let rdnmNoTemp1 = sbx_mvprpRpdtEmdLst.getValue();
            let rdnmNoTemp2 = rdnmNoTemp1.split("|")
            if (rdnmNoTemp2[1] === 'A') {//지번
                cortStDvs = '2'
                mvprpDspslPlcAdongSdCd = sbx_mvprpRpdtSdLst.getValue()
                mvprpDspslPlcAdongSggCd = sbx_mvprpRpdtSggLst.getValue();
                mvprpDspslPlcAdongEmdCd = rdnmNoTemp2[0]

            } else if(rdnmNoTemp2[1] === 'R') { //도로명
                cortStDvs = '3'
                rdDspslPlcAdongSdCd = sbx_mvprpRpdtSdLst.getValue();
                rdDspslPlcAdongSggCd = sbx_mvprpRpdtSggLst.getValue();
                rdDspslPlcAdongEmdCd = rdnmNoTemp2[0]
            } else {
                cortStDvs = '2'
                mvprpDspslPlcAdongSdCd = sbx_mvprpRpdtSdLst.getValue()
                mvprpDspslPlcAdongSggCd = sbx_mvprpRpdtSggLst.getValue();
            }
        }
    }
    const srchInfo = {
        cortOfcCd, mvprpRletDvsCd, rdnmSdCd, rdnmSggCd, rdnmNo,
        rdDspslPlcAdongSdCd, rdDspslPlcAdongSggCd, rdDspslPlcAdongEmdCd
        , cortAuctnSrchCondCd, cortStDvs,rprsAdongSdCd,rprsAdongSggCd,rprsAdongEmdCd
        , mvprpDspslPlcAdongSdCd, mvprpDspslPlcAdongSggCd, mvprpDspslPlcAdongEmdCd

    }
    param.srchInfo = srchInfo
    pgjUtil.openGdsDtl(param);

};


