 * ============= ============ ==========================
 */
scwin.anc_rletGnrlDxdyTitle_onclick = function() {
    const _thisDxdy = $p.getComponentById(this.id);
    const grpNum = _thisDxdy.getUserData("grpNum");
    const idx = _thisDxdy.getUserData("idx");
    const lst = scwin.rletPbanc[grpNum]
    const orgObj = Object.fromEntries(lst[idx]) // Map 형태를 다시 일반 객체로 변환

    $p.local.setItem('dxdySrchParm', JSON.stringify(orgObj)  );
    $p.url("/pgj/ui/pgj100/PGJ141M00.xml",{"spa" : false, "replaceHistory" : true,"param":{pgjId : '143M02'}})
};

