/**
 *
 * 금주경매 일정 클릭시 이동하는 이벤트 (부동산 취소)
 *
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.20.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.anc_rletRtrcnDxdyTitle_onclick = function() {
    const _thisDxdy = $p.getComponentById(this.id);
    const grpNum = _thisDxdy.getUserData("grpNum");
    const idx = _thisDxdy.getUserData("idx");
    let lst = scwin.rletRtrcnPbanc[grpNum]
    const orgObj = Object.fromEntries(lst[idx]) // Map 형태를 다시 일반 객체로 변환

    $p.local.setItem('dxdySrchParm', JSON.stringify(orgObj)  );
    $p.url("/pgj/ui/pgj100/PGJ141M00.xml",{"spa" : false, "replaceHistory" : true,"param":{pgjId : '143M03'}})
};


