/**
 *
 * 빠른검색 검색 유형별 페이지 이동 이벤트
 * type : [1] : 물건상세검색
 *        [2] : 지도검색
 *        [3] : 자동차,중기검색
 *        [4] : 사건검색
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.08.07.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.fastSrchMoveUrl = function(type) {
    const flag = type;
    switch(flag) {
        case "1" :
            $p.url("/pgj/ui/pgj100/PGJ151F00.xml")
            break
        case "2" :
            scwin.btnMapInfo_onclick();
            break
        case "3" :
            $p.url("/pgj/ui/pgj100/PGJ154M00.xml")
            break
        case "4" :
            $p.url("/pgj/ui/pgj100/PGJ159M00.xml")
            break
    }
};

/**
 *
 * 지도안내문 팝업 호출
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.08.07.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btnMapInfo_onclick = function() {

    /********* Popup Settings *********/
    var winW = window.innerWidth;
    var winH = window.innerHeight;

    /* default popup size */
    var popupW = 700;
    var popupH = 450;

    var popupX = (winW/2) - (popupW/2);
    var popupY = (winH/2) - (popupH/2);

    var options = {
        id: "popupMapGuide",
        type: "wframePopup",
        modal: true,
        popupName: "지도_안내문",
        top:popupY,
        left:popupX,
        width:popupW,
        height:popupH,
    };

    com.win.openPopup("/pgj/ui/pgj100/PGJ152P01.xml", options);
}

/**
 *
 * menu이동 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.26.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_oftenUsingMenu_onchange = function(info) {
    const menuId = info.newValue;
    switch (menuId) {
        case 'PGJ155M00_1' :
            $p.url("/pgj/ui/pgj100/PGJ155M00.xml",{"spa" : false, "replaceHistory" : true,"param":'1'})
            break;
        case 'PGJ155M00_2' :
            $p.url("/pgj/ui/pgj100/PGJ155M00.xml",{"spa" : false, "replaceHistory" : true,"param":'2'})
            break
        case 'EditMember' :
            wfm_header.getWindow().scwin.btnEditMember_onclick()
            break
        case 'PGJ141M01' :
        case 'PGJ142M01' :
        case 'PGJ143M01' :
        case 'PGJ144M01' :
            $p.url("/pgj/ui/pgj100/PGJ141M00.xml",{"spa" : false, "replaceHistory" : true,"param":{pgjId : menuId.slice(3)}})
            break
        default : $p.url(`/pgj/ui/pgj100/${menuId}.xml`)
    }

};

scwin.btn_oftenUsingMenu_onclick = function(e) {
    $p.url(`/pgj/ui/pgj100/PGJ195M03.xml`)
};
